// bug-01: map the household form submission to a Forgejo issue payload.
// Two required fields (activity + what-happened); the rest are optional. Field keys
// are the field LABELS (formTrigger typeVersion 2.2). Reads defensively.
const f = $input.first().json;
const get = (k) => { const v = f[k]; return (v == null ? '' : String(v)).trim(); };
const activity = get('What were you trying to do?');
const what     = get('What happened?');
const where    = get('Where were you? (which device or room)');
const when     = get('When did it happen?');
const sevRaw   = get('How much is it bothering you?');

const A = activity.toLowerCase();
let label = 'service:triage', svc = '(unknown — needs triage)', actName = 'Something else';
if (A.includes('watch'))            { label='service:plex';       svc='Plex / Jellyfin';                                   actName='Watch'; }
else if (A.includes('listen'))      { label='service:navidrome';  svc='Navidrome / Audiobookshelf';                        actName='Listen'; }
else if (A.includes('photo'))       { label='service:immich';     svc='Immich';                                            actName='Photos'; }
else if (A.includes('read'))        { label='service:komga';      svc='Audiobookshelf / Komga / Calibre-Web / Suwayomi';   actName='Read'; }
else if (A.includes('journal'))     { label='service:journaling'; svc='Memos / n8n';                                       actName='Journal'; }
else if (A.includes('dashboard') || A.includes('home page')) { label='service:homepage'; svc='Homepage'; actName='Dashboard'; }
else if (A.includes('game'))        { label='service:games';      svc='AMP / Palworld';                                    actName='Game'; }
else if (A.includes('request'))     { label='service:seerr';      svc='Seerr / Musicseerr / Shelfmark';                    actName='Request'; }

// light where-based disambiguation
let hint = '';
if (label === 'service:plex' && /tv|telly|living/i.test(where)) hint = ' (likely Plex on the TV)';

let sevLabel = 'sev:annoying', sevWord = 'Annoying (unspecified)';
if (/block/i.test(sevRaw))      { sevLabel='sev:blocking'; sevWord='Blocking'; }
else if (/annoy/i.test(sevRaw)) { sevLabel='sev:annoying'; sevWord='Annoying'; }

const labelNames = ['source:home', label, sevLabel];

const firstLine = ((what.split(/\r?\n/)[0]) || what || 'Problem reported').slice(0, 80);
const title = '[' + actName + '] ' + firstLine;

let body = '**What were you trying to do?** ' + (activity || '_(not provided)_') + '\n\n';
body += '**What happened?**\n' + (what || '_(not provided)_') + '\n\n';
body += '**Likely service(s):** ' + svc + hint + '\n';
if (where) body += '**Where / device:** ' + where + '\n';
if (when)  body += '**When:** ' + when + '\n';
body += '**Severity:** ' + sevWord + '\n';
body += '\n---\n_Filed from the household “Report a Problem” form (bug.tabaska.us). Auto-labeled; the service guess may be off — triage as needed._';

const bin = $input.first().binary || {};
const screenshotKey = Object.keys(bin)[0] || '';
const hasScreenshot = !!screenshotKey;

return [{ json: { title, body, labelNames, activity: actName, service: svc, severity: sevWord, whatShort: firstLine, what, where, when, hasScreenshot }, binary: $input.first().binary }];

// Resolve label NAMES -> Forgejo label IDs (Gitea 1.22 create-issue takes IDs, not
// names). Best-effort: if the labels fetch failed, post the issue with no labels.
const p = $('Build issue payload').first().json;
let labels = $input.all().map(i => i.json);
if (labels.length === 1 && Array.isArray(labels[0])) labels = labels[0];
labels = labels.filter(x => x && x.name != null && x.id != null);
const byName = {};
for (const l of labels) byName[l.name] = l.id;
const ids = (p.labelNames || []).map(n => byName[n]).filter(x => x != null);
return [{ json: { title: p.title, body: p.body, labelIds: ids, hasScreenshot: p.hasScreenshot },
          binary: $('Build issue payload').first().binary }];

// Screenshot side-branch: needs the new issue number (from Create) AND the uploaded
// binary (from the form trigger). Rename the first binary to a fixed key 'screenshot'
// so the upload node has a static field name. No screenshot -> return [] (branch ends).
const issue = $input.first().json;
const num = issue && issue.number;
const src = $('Report a Problem').first();
const bin = (src && src.binary) ? src.binary : {};
const key = Object.keys(bin)[0] || '';
if (!num || !key) return [];
const meta = bin[key] || {};
const filename = meta.fileName || ('screenshot' + (meta.fileExtension ? '.' + meta.fileExtension : '.png'));
return [{ json: { issueNumber: num, filename }, binary: { screenshot: bin[key] } }];

// Build the ntfy + Discord notification payloads from the created issue.
const issue = $('Create Forgejo issue').first().json;
const p = $('Build issue payload').first().json;
const num = issue && issue.number ? issue.number : '?';
const link = 'https://git.tabaska.us/home/household-bugs/issues/' + num;
// ntfy Title header must be ASCII-safe (no emoji in headers) -> emoji only in body.
const title = 'New bug report: ' + p.activity;
const msg = '\u{1F41E} ' + p.whatShort + '\n\nService: ' + p.service + '\nSeverity: ' + p.severity + '\n' + link;
const priority = /block/i.test(p.severity) ? '4' : '3';
const dw = ($env.DISCORD_BUGS_WEBHOOK || '').trim();
const discordSet = dw.length > 0;
const discordBody = { content: '\u{1F41E} **New household bug report** — ' + p.activity + ' (' + p.severity + ')\n' + p.whatShort + '\n' + link };
// The verification synthetic-submit probe files a report carrying this sentinel; the
// issue is still created (so the create path is exercised end-to-end) but we SKIP the
// ntfy/Discord ping so a monitoring run never buzzes the operator's phone. The probe
// deletes the issue afterward, leaving zero residue.
const notify = !/n8n-bugreport-probe|n8n-triage-probe/i.test(p.whatShort || '');
return [{ json: { title, msg, priority, link, discordSet, discordBody, notify } }];

// bug-02: map the freshly-created issue to a read-only probe service key + decide
// whether to run triage. Skip only the bug-01 form-armed sentinel (n8n-bugreport-probe)
// to avoid extra LLM load on that daily check; the bug-02 sentinel (n8n-triage-probe)
// DOES run so the triage E2E exercises the full loop.
const p = $('Build issue payload').first().json;
const issue = $('Create Forgejo issue').first().json;
const svcLabel = (p.labelNames || []).find(n => n.startsWith('service:')) || 'service:triage';
const service = svcLabel.replace('service:', '');
const runTriage = !/n8n-bugreport-probe/i.test(p.whatShort || '');
return [{ json: { service, issueNumber: (issue && issue.number) || null,
  activity: p.activity, whatShort: p.whatShort, what: p.what || p.whatShort || '',
  where: p.where || '', when: p.when || '', runTriage } }];

// bug-02: assemble the single-shot triage chat payload from the evidence bundle + the
// household report. The rig only ever sees this prose+evidence (no fleet access).
const t = $('Prep triage').first().json;
let ev = {};
try { ev = $('Gather evidence').first().json || {}; } catch (e) { ev = {}; }
if (ev && ev.error && !ev.service) ev = { service: t.service, evidence_error: ev.error };
const SYS = "You are a READ-ONLY triage assistant for a self-hosted homelab. Input: a household bug report plus machine-gathered EVIDENCE with these parts: docker (container state/logs), http (health probes), context (background facts), expected_states (documented NORMAL conditions that can cause a symptom).\\n\\nHARD RULES:\\n- OBSERVE-ONLY: never propose restart/fix commands or any action.\\n- Ground every claim ONLY in the evidence. NEVER invent notes, jobs, schedules, or causes not present in the evidence.\\n- \\\"Expected state?\\\" = yes ONLY if an entry in expected_states actually explains this symptom (quote which one). The context section is background ONLY and is never by itself a reason to answer yes. If expected_states is empty or none explains the symptom, answer no even when every probe looks healthy (the cause may be downstream/unknown).\\n\\nEXAMPLE A (expected_states explains it -> yes):\\nReport: Photos face-search stuck during the day; browsing works. expected_states mentions Immich ML is night-gated and daytime face-search backfill is deferred.\\nDiagnosis: Your photos and albums are fine - browsing and uploading work normally. Only the AI face/subject search is paused, on purpose, during the day.\\nExpected state?: yes - Immich ML night-window (face/smart-search backfill deferred to 01:00-07:00).\\nLikely cause: Immich ML is intentionally night-gated; daytime face-search delay is expected, not a fault.\\nConfidence: high\\n\\nEXAMPLE B (probes healthy, expected_states empty -> no, do NOT invent):\\nReport: I requested a movie two days ago and it never arrived. Probes show the request UI healthy; expected_states is empty; context says downstream download is not probed.\\nDiagnosis: The request website is up and working, but nothing in this evidence shows what happened after you submitted; the download/library side, which is not checked here, is the likely place it stalled.\\nExpected state?: no - request UI healthy but no expected_state explains it; cause is downstream and not visible here.\\nLikely cause: Request UI healthy; likely a downstream indexer/download/library issue this evidence does not cover.\\nConfidence: medium\\n\\nAnswer the REAL report in EXACTLY this template, nothing else:\\nDiagnosis: <2-4 plain sentences for a non-technical operator>\\nExpected state?: <yes - quote the expected_state | no>\\nLikely cause: <one line>\\nConfidence: <low|medium|high>";
const report = 'Activity: ' + t.activity + '\nWhat happened: ' + (t.what || t.whatShort) +
  (t.where ? '\nWhere/device: ' + t.where : '') + (t.when ? '\nWhen: ' + t.when : '');
const user = 'BUG REPORT\n' + report + '\n\nEVIDENCE (read-only, machine-gathered):\n' +
  JSON.stringify(ev, null, 1);
const chatBody = { model: 'utility', messages: [ { role: 'system', content: SYS },
  { role: 'user', content: user } ], temperature: 0.15, max_tokens: 450 };
return [{ json: { issueNumber: t.issueNumber, service: t.service, chatBody, evidence: ev } }];

// bug-02: turn the LLM reply (or its absence) into a Forgejo issue comment. On any
// model failure/empty content we DEGRADE to an evidence-only comment (SKIP, not FAIL)
// per the best-effort ceiling (rig 24B may be GPU-contended). Also resolves the
// 'triaged' label id from the labels already fetched earlier in the run.
const src = $('Build triage prompt').first().json;
const ev = src.evidence || {};
let content = '';
try { content = (($input.first().json.choices || [])[0].message.content || '').trim(); }
catch (e) { content = ''; }
function digest(ev) {
  let s = '';
  if (Array.isArray(ev.docker) && ev.docker.length)
    s += '- **Containers (mini):** ' + ev.docker.map(d => d.name + ': ' + (d.status || d.error || d.state || '?')).join('; ') + '\n';
  if (Array.isArray(ev.http) && ev.http.length)
    s += '- **Health probes:** ' + ev.http.map(h => h.name + '=' + (h.status == null ? 'ERR' : h.status)).join('; ') + '\n';
  if (Array.isArray(ev.expected_states) && ev.expected_states.length)
    s += '- **Known expected-states considered:** ' + ev.expected_states.length + '\n';
  return s || '_(no evidence gathered)_\n';
}
const foot = '\n\n<sub>\uD83D\uDD0E Auto-triage \u2014 READ-ONLY: the mini gathered evidence, the rig reasoned. No fleet state was changed and no fix was run. The service guess and diagnosis are advisory \u2014 re-triage as needed.</sub>';
const meta = '\n_service: ' + (ev.service || src.service) + ' \u00b7 generated ' + (ev.generated_at || 'n/a') + '_\n';
let body, degraded = false;
if (content) {
  body = '## \uD83D\uDD0E Auto-triage (read-only)\n\n' + content +
    '\n\n<details><summary>Evidence gathered</summary>\n\n' + digest(ev) + meta + '</details>' + foot;
} else {
  degraded = true;
  body = '## \uD83D\uDD0E Auto-triage \u2014 evidence only\n\n' +
    'The reasoning model was unavailable (best-effort degrade \u2014 likely rig GPU contention). ' +
    'Posting the machine-gathered evidence without a diagnosis; re-run or triage by hand.\n\n' +
    digest(ev) + meta + foot;
}
let triagedId = null;
try {
  let labels = $('Get labels').all().map(i => i.json);
  if (labels.length === 1 && Array.isArray(labels[0])) labels = labels[0];
  const hit = labels.find(l => l && l.name === 'triaged');
  if (hit) triagedId = hit.id;
} catch (e) {}
return [{ json: { issueNumber: src.issueNumber, body, degraded, triagedId } }];
